import "./App.css";
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const Home = () => {
  const [posts, setPosts] = useState([]);

  useEffect(() => {
    let isMounted = true;

    const fetchRecentPosts = async () => {
      try {
        const response = await fetch(
          "https://www.instagram.com/api/v1/users/web_profile_info/?username=frnkastro",
          {
            headers: {
              Accept: "application/json",
              "X-IG-App-ID": "936619743392459",
              "X-Requested-With": "XMLHttpRequest",
              Referer: "https://www.instagram.com/",
            },
          }
        );

        if (!response.ok) {
          throw new Error(`Instagram request failed: ${response.status}`);
        }

        const json = await response.json();
        const recentPosts =
          json?.data?.user?.edge_owner_to_timeline_media?.edges?.map(({ node }) => ({
            id: node.id,
            image: node.display_url || node.thumbnail_src,
            shortcode: node.shortcode,
            isVideo: node.is_video,
            caption:
              node.edge_media_to_caption?.edges?.[0]?.node?.text ||
              "frnk astro post",
          })) || [];

        if (isMounted) {
          setPosts(recentPosts.slice(0, 3));
        }
      } catch (error) {
        if (isMounted) {
          setPosts([]);
        }
      }
    };

    fetchRecentPosts();

    return () => {
      isMounted = false;
    };
  }, []);

  return (
    <main>
      <div className="content">
        <h1 className="band-name">frnk astro</h1>
        <p className="sub-headline">Denver, CO Indie Basement Rock</p>

        <div className="button-container">
          <div className="primary-buttons">
            <Link
              to="/shows"
              className="link-btn primary"
              aria-label="View upcoming frnk astro shows"
            >
              Shows
            </Link>
          </div>

          <div className="secondary-buttons">
            <Link
              to="/videos"
              className="link-btn secondary"
              aria-label="View frnk astro videos"
            >
              Videos
            </Link>
            <a
              href="https://frnkastro.bandcamp.com"
              target="_blank"
              rel="noreferrer"
              className="link-btn secondary"
              aria-label="Listen to frnk astro on Bandcamp"
            >
              Listen on Bandcamp
            </a>
            <a
              href="https://soundcloud.com/frnkastro"
              target="_blank"
              rel="noreferrer"
              className="link-btn secondary"
              aria-label="Listen to frnk astro on SoundCloud"
            >
              Listen on SoundCloud
            </a>
            <a
              href="https://instagram.com/frnkastro"
              target="_blank"
              rel="noreferrer"
              className="link-btn secondary"
              aria-label="Please help us be cool"
            >
              Become frnk astro's First Instagram Follower
            </a>
            <a
              href="mailto:frnkastroparty@gmail.com"
              className="link-btn secondary"
              aria-label="Get in touch with frnk astro"
            >
              Get in Touch
            </a>
          </div>
        </div>
      </div>

      <section className="instagram-section" aria-label="Recent Instagram posts">
        <div className="instagram-header">
          <span className="instagram-label">Instagram</span>
          <a
            className="instagram-link"
            href="https://instagram.com/frnkastro"
            target="_blank"
            rel="noreferrer"
          >
            @frnkastro
          </a>
        </div>

        <div className="instagram-grid">
          {posts.length > 0 ? (
            posts.map((post) => (
              <a
                key={post.id}
                className="instagram-post"
                href={`https://www.instagram.com/p/${post.shortcode}/`}
                target="_blank"
                rel="noreferrer"
                aria-label={post.caption}
              >
                <img src={post.image} alt={post.caption} />
                {post.isVideo && <span className="video-indicator">Video</span>}
              </a>
            ))
          ) : (
            <p className="instagram-fallback">
              Recent posts are unavailable right now — follow us on Instagram for
              the latest.
            </p>
          )}
        </div>
      </section>

      <footer className="footer">Denver, CO • frnkastroparty@gmail.com</footer>
    </main>
  );
};

export default Home;
